import React, { useState, useRef, useEffect } from 'react';

import { cn } from '@/utils/index';

interface Option {
  value: string;
  label: string;
}

interface CustomSelectProps {
  options: Option[];
  value: string | string[];
  onChange: (value: string | string[]) => void;
  placeholder?: string;
  size?: 'normal' | 'wide';
  multiSelect?: boolean;
  hasError?: boolean;
}

export const CustomSelect: React.FC<CustomSelectProps> = ({
  options,
  value,
  onChange,
  placeholder = 'Выберите опцию',
  size = 'normal',
  multiSelect = false,
  hasError = false
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const selectRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (selectRef.current && !selectRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Нормализуем value в массив для удобства работы
  const selectedValues = Array.isArray(value) ? value : (value ? [value] : []);
  const selectedOptions = options.filter(option => selectedValues.includes(option.value));

  const handleOptionClick = (optionValue: string) => {
    if (multiSelect) {
      const newValues = selectedValues.includes(optionValue)
        ? selectedValues.filter(v => v !== optionValue)
        : [...selectedValues, optionValue];
      onChange(newValues);
    } else {
      onChange(optionValue);
      setIsOpen(false);
    }
  };

  const removeTag = (optionValue: string) => {
    const newValues = selectedValues.filter(v => v !== optionValue);
    onChange(newValues);
  };

  return (
    <div className={cn('vk-custom-select', size === 'wide' && 'vk-custom-select--wide', hasError && 'vk-custom-select--error')} ref={selectRef}>
      <div
        className={cn('vk-custom-select__trigger', isOpen && 'vk-custom-select__trigger--open')}
        onClick={() => setIsOpen(!isOpen)}
      >
        {selectedOptions.length > 0 ? (
          multiSelect ? (
            <div className="vk-custom-select__tags">
              {selectedOptions.map(option => (
                <span key={option.value} className="vk-custom-select__tag">
                  {option.label}
                  <button
                    type="button"
                    className="vk-custom-select__tag-remove"
                    onClick={(e) => {
                      e.stopPropagation();
                      removeTag(option.value);
                    }}
                  >
                    ×
                  </button>
                </span>
              ))}
            </div>
          ) : (
            <span className="vk-custom-select__selected">{selectedOptions[0].label}</span>
          )
        ) : (
          <span className="vk-custom-select__placeholder">{placeholder}</span>
        )}
        <span className={cn('vk-custom-select__arrow', isOpen && 'vk-custom-select__arrow--open')}>▼</span>
      </div>

      {isOpen && (
        <div className="vk-custom-select__dropdown">
          {options.map(option => (
            <div
              key={option.value}
              className={cn('vk-custom-select__option', selectedValues.includes(option.value) && 'vk-custom-select__option--selected')}
              onClick={() => handleOptionClick(option.value)}
            >
              {option.label}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useCallback, useState } from 'react';
import { cn } from '@/utils/index';

interface FileUploaderProps {
  onFileSelect: (files: FileList) => void;
  accept?: string;
  multiple?: boolean;
  maxSize?: number; // в байтах
  className?: string;
}

export const FileUploader: React.FC<FileUploaderProps> = ({
  onFileSelect,
  accept = '*/*',
  multiple = false,
  maxSize = 10 * 1024 * 1024, // 10MB по умолчанию
  className
}) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const validateFiles = useCallback((files: FileList) => {
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (file.size > maxSize) {
        setError(`Файл ${file.name} слишком большой. Максимальный размер: ${Math.round(maxSize / 1024 / 1024)}MB`);
        return false;
      }
    }
    setError(null);
    return true;
  }, [maxSize]);

  const handleDrop = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragOver(false);

    const files = e.dataTransfer.files;
    if (files.length > 0 && validateFiles(files)) {
      onFileSelect(files);
    }
  }, [onFileSelect, validateFiles]);

  const handleDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragOver(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragOver(false);
  }, []);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0 && validateFiles(files)) {
      onFileSelect(files);
    }
    // Сбрасываем input для возможности повторного выбора того же файла
    e.target.value = '';
  }, [onFileSelect, validateFiles]);

  return (
    <div className={cn('vk-file-uploader', className)}>
      <div
        className={cn('vk-file-uploader__drop-zone', isDragOver && 'vk-file-uploader__drop-zone--drag-over')}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
      >
        <input
          type="file"
          accept={accept}
          multiple={multiple}
          onChange={handleFileInput}
          className="vk-file-uploader__input"
          id="file-input"
        />
        <label htmlFor="file-input" className="vk-file-uploader__label">
          <div className="vk-file-uploader__icon">📁</div>
          <div className="vk-file-uploader__text">
            Перетащите файлы сюда или <span className="vk-file-uploader__link">выберите</span>
          </div>
          {multiple && <div className="vk-file-uploader__hint">Можно выбрать несколько файлов</div>}
        </label>
      </div>
      {error && <div className="vk-file-uploader__error">{error}</div>}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { cn } from '@/utils/index';

interface Party {
  id: string;
  name: string;
  inn?: string;
  type: 'individual' | 'legal';
}

interface PartySelectorProps {
  value?: Party;
  onChange: (party: Party | null) => void;
  onSearch?: (query: string) => Promise<Party[]>;
  placeholder?: string;
  required?: boolean;
  className?: string;
}

export const PartySelector: React.FC<PartySelectorProps> = ({
  value,
  onChange,
  onSearch,
  placeholder = 'Введите ИНН или название',
  required = false,
  className
}) => {
  const [query, setQuery] = useState(value?.name || '');
  const [suggestions, setSuggestions] = useState<Party[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (query.length >= 3 && onSearch) {
      setIsLoading(true);
      onSearch(query)
        .then(setSuggestions)
        .finally(() => setIsLoading(false));
    } else {
      setSuggestions([]);
    }
  }, [query, onSearch]);

  const handleSelect = (party: Party) => {
    setQuery(party.name);
    onChange(party);
    setIsOpen(false);
  };

  const handleClear = () => {
    setQuery('');
    onChange(null);
    setSuggestions([]);
  };

  return (
    <div className={cn('vk-party-selector', className)}>
      <div className="vk-party-selector__input-wrapper">
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onFocus={() => setIsOpen(true)}
          placeholder={placeholder}
          required={required}
          className={cn('vk-party-selector__input', value && 'vk-party-selector__input--selected')}
        />
        {value && (
          <button
            type="button"
            onClick={handleClear}
            className="vk-party-selector__clear"
            aria-label="Очистить"
          >
            ×
          </button>
        )}
      </div>

      {isOpen && (suggestions.length > 0 || isLoading) && (
        <div className="vk-party-selector__dropdown">
          {isLoading ? (
            <div className="vk-party-selector__loading">Поиск...</div>
          ) : (
            suggestions.map(party => (
              <div
                key={party.id}
                onClick={() => handleSelect(party)}
                className="vk-party-selector__option"
              >
                <div className="vk-party-selector__option-name">{party.name}</div>
                {party.inn && (
                  <div className="vk-party-selector__option-inn">ИНН: {party.inn}</div>
                )}
                <div className="vk-party-selector__option-type">
                  {party.type === 'legal' ? 'Юридическое лицо' : 'Физическое лицо'}
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};
